import type { BankQuestion } from "@/lib/bank";

/** Climate and Monsoon of India (Geography): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "geo-climate-monsoon-1", "question": "The climate of India is broadly described as:", "options": ["Tropical monsoon type", "Cold temperate type", "Equatorial type", "Mediterranean type"], "answer": 0, "explanation": "India has a tropical monsoon climate: a seasonal reversal of winds brings a wet summer and a largely dry winter.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-2", "question": "The word “monsoon” is derived from an Arabic word meaning:", "options": ["Rain", "Wind", "Season", "Storm"], "answer": 2, "explanation": "“Monsoon” comes from the Arabic “mausim”, meaning season, because the winds reverse direction with the seasons.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-3", "question": "According to the IMD's four-season division, the retreating (post-monsoon) season covers:", "options": ["October–November", "December–February", "March–May", "June–September"], "answer": 0, "explanation": "The IMD seasons are winter (Dec–Feb), hot weather (Mar–May), south-west monsoon (Jun–Sep) and retreating monsoon (Oct–Nov).", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-4", "question": "In most of north India, the coldest month of the year is:", "options": ["January", "November", "May", "March"], "answer": 0, "explanation": "January is the coldest month over the northern plains; mean temperatures then fall to about 10–15 °C.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-5", "question": "The normal date of onset of the south-west monsoon over Kerala is around:", "options": ["1 July", "15 June", "15 May", "1 June"], "answer": 3, "explanation": "The IMD's normal onset date over Kerala is 1 June (give or take about a week); by mid-June the monsoon normally reaches central India.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-6", "question": "The winter rain brought to Punjab and Haryana by western disturbances is most useful for:", "options": ["Jute", "Cotton", "Wheat", "Rice"], "answer": 2, "explanation": "Light winter rain from western disturbances helps the rabi crops, especially wheat; rice, jute and cotton are kharif crops.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-7", "question": "Pre-monsoon “mango showers”, which help the early ripening of mangoes, are a feature of:", "options": ["Rajasthan and Gujarat", "Punjab and Haryana", "Kerala and coastal Karnataka", "Assam and West Bengal"], "answer": 2, "explanation": "Mango showers fall in April–May along the Kerala and Karnataka coasts; the evening storms of Bengal and Assam are the Nor'westers (Kalbaisakhi).", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-8", "question": "Which of these places receives the lowest average annual rainfall?", "options": ["Shillong", "Chennai", "Jaisalmer", "Kolkata"], "answer": 2, "explanation": "Western Rajasthan, around Jaisalmer, gets well under 25 cm a year; Chennai, Kolkata and Shillong each receive more than 100 cm.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-9", "question": "The south-east trade winds of the southern hemisphere turn into the south-west monsoon winds after crossing the equator because of:", "options": ["Western disturbances", "Katabatic flow down the Himalaya", "The Coriolis force", "The Loo"], "answer": 2, "explanation": "The Coriolis force deflects winds to the right in the northern hemisphere, so the south-easterlies become south-westerlies once they cross the equator.", "difficulty": "moderate", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-10", "question": "Severe tropical cyclones hitting the Odisha and Andhra Pradesh coasts are most frequent in:", "options": ["October–November", "July–August", "January–February", "December–January"], "answer": 0, "explanation": "Cyclone activity in the Bay of Bengal peaks in the post-monsoon months of October–November, with a smaller peak in April–May; in July–August strong wind shear limits cyclone formation.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-11", "question": "In July, the Inter-Tropical Convergence Zone (the monsoon trough) over India lies roughly along:", "options": ["About 5°S over the Indian Ocean", "About 35°N over Ladakh", "The Ganga plain, about 20°–25°N", "The equator"], "answer": 2, "explanation": "In summer the ITCZ moves north and settles over the Ganga plain at about 20°–25°N, pulling in the monsoon winds; in winter it moves south of the equator.", "difficulty": "moderate", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-12", "question": "The hot, humid spell over much of India after the monsoon withdraws, when skies clear but the ground is still wet, is called:", "options": ["October heat", "Mango shower", "Loo", "Kalbaisakhi"], "answer": 0, "explanation": "High temperatures plus high humidity after the monsoon retreats make the weather oppressive; this is known as “October heat”.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-13", "question": "The tropical easterly jet stream, which strengthens the south-west monsoon, blows:", "options": ["Over the Ganga plain in winter", "Over peninsular India at about 14°N in summer", "Near the surface over the Arabian Sea in winter", "Over the Himalaya in winter"], "answer": 1, "explanation": "In summer an upper-tropospheric easterly jet sets up over the peninsula at about 14°N; in winter it is the subtropical westerly jet that lies over north India.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-14", "question": "The sudden “burst” of the monsoon over north India in June is linked mainly to:", "options": ["The subtropical westerly jet shifting north of the Himalaya", "The Loo intensifying over Rajasthan", "Western disturbances entering from Iran", "The winter high over the Thar"], "answer": 0, "explanation": "As long as the westerly jet lies south of the Himalaya the monsoon cannot advance; when it jumps north of the Himalaya, the monsoon bursts over north India.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-15", "question": "El Niño, often associated with a weaker Indian monsoon, refers to:", "options": ["Warming of the western Indian Ocean relative to the east", "Strengthening of the Somali current", "Abnormal cooling of surface waters of the central Pacific", "Abnormal warming of surface waters of the central and eastern equatorial Pacific"], "answer": 3, "explanation": "El Niño is the warming of the eastern and central equatorial Pacific off Peru; cooling there is La Niña, and a warmer western Indian Ocean is a positive Indian Ocean Dipole.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-16", "question": "In a positive Indian Ocean Dipole (IOD) event:", "options": ["The whole Indian Ocean cools uniformly", "The Pacific off Peru turns cold", "The eastern Indian Ocean is warmer than the western, which usually helps the monsoon", "The western Indian Ocean is warmer than the eastern Indian Ocean, which usually helps the Indian monsoon"], "answer": 3, "explanation": "A positive IOD means warmer sea surface in the western Indian Ocean (near Africa) than in the east (near Sumatra); this generally favours good monsoon rain over India.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-17", "question": "The Southern Oscillation Index is calculated from the difference in sea-level pressure between:", "options": ["Tahiti and Darwin", "Mumbai and Chennai", "Madagascar and Perth", "Lima and Jakarta"], "answer": 0, "explanation": "The Southern Oscillation is a see-saw of pressure across the Pacific, measured between Tahiti (central Pacific) and Darwin (northern Australia).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-18", "question": "The strong low-level cross-equatorial air current off the East African coast that carries moisture to India's west coast is the:", "options": ["Polar front jet", "Kuroshio current", "Tropical easterly jet", "Somali (Findlater) jet"], "answer": 3, "explanation": "The Somali or Findlater jet is a low-level jet along the East African highlands that feeds the Arabian Sea branch of the monsoon; the tropical easterly jet is an upper-level wind.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-19", "question": "The Tamil Nadu coast receives little rain during the south-west monsoon because:", "options": ["The monsoon never reaches south India", "Cold ocean currents flow along it in summer", "It lies on the windward side of the Western Ghats", "It lies in the rain shadow of the Arabian Sea branch and runs parallel to the Bay of Bengal branch"], "answer": 3, "explanation": "The Western Ghats block the Arabian Sea branch, and the Bay of Bengal branch blows parallel to the Coromandel coast instead of onto it, so the coast stays relatively dry until October.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-20", "question": "The variability (coefficient of variation) of annual rainfall in India is highest in:", "options": ["The Konkan coast", "Coastal Kerala", "Western Rajasthan", "Meghalaya"], "answer": 2, "explanation": "Variability is inversely related to the amount of rain: low-rainfall western Rajasthan shows variability above 50%, while the wet west coast and north-east are far more dependable.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-21", "question": "The violent pre-monsoon evening thunderstorms called Kalbaisakhi in West Bengal are known in Assam as:", "options": ["Bardoli Chheerha", "Blossom showers", "Mango showers", "Loo"], "answer": 0, "explanation": "In Assam the Nor'westers are called “Bardoli Chheerha”; they help tea, jute and rice. Blossom and mango showers belong to Karnataka and Kerala.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-22", "question": "A “break” in the monsoon over the northern plains usually occurs when:", "options": ["Western disturbances bring heavy rain to the plains", "The monsoon trough shifts south to the equator", "The monsoon trough shifts north to the Himalayan foothills", "The tropical easterly jet strengthens over the peninsula"], "answer": 2, "explanation": "When the axis of the monsoon trough moves to the foothills, rain stops over the plains but becomes heavy in the Himalayan foothills and the north-east.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-23", "question": "Which is normally the wettest month at Chennai?", "options": ["July", "June", "November", "August"], "answer": 2, "explanation": "Chennai gets most of its rain from the north-east monsoon and Bay of Bengal depressions in October–December, with November the wettest month; July and August are relatively dry there.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-24", "question": "The withdrawal of the south-west monsoon normally begins from:", "options": ["Kerala in August", "Assam in July", "Tamil Nadu in October", "North-west India (west Rajasthan) in September"], "answer": 3, "explanation": "The monsoon retreats in the reverse order of its arrival, starting from west Rajasthan in September; it leaves the southern peninsula last.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-25", "question": "How many of the following statements are correct? I. During La Niña, sea-surface temperatures in the eastern equatorial Pacific are below normal. II. Every El Niño year has produced a drought in India. III. The Walker circulation weakens during an El Niño. IV. A strong positive Indian Ocean Dipole can offset the effect of an El Niño on the Indian monsoon.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct; 1997 was a strong El Niño year with near-normal Indian rain, helped by a positive IOD. II is wrong: El Niño raises the risk of a weak monsoon but does not always cause drought.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-26", "question": "Match the local wind with its description. A. Chinook  B. Foehn  C. Sirocco  D. Harmattan; 1. Hot, dusty wind from the Sahara reaching Italy  2. Dry, dusty wind over West Africa, nicknamed “the doctor”  3. Warm wind descending the eastern slopes of the Rockies  4. Warm, dry wind on the leeward side of the Alps", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-3, B-4, C-2, D-1", "A-3, B-2, C-1, D-4"], "answer": 1, "explanation": "The Chinook (“snow eater”) blows down the Rockies, the Foehn down the northern Alps, the Sirocco from the Sahara to southern Europe, and the Harmattan over the Guinea coast, where its dryness relieves the humid heat.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-27", "question": "Match the Indian weather phenomenon with its description. A. Loo  B. Kalbaisakhi  C. Mango showers  D. Blossom showers; 1. Pre-monsoon showers in Kerala and coastal Karnataka that help ripen mangoes  2. Hot, dry afternoon wind over the plains from Punjab to Bihar  3. Showers that make coffee flowers bloom in Kerala and nearby areas  4. Evening thunderstorms of West Bengal in the month of Baisakh", "options": ["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-4, B-2, C-1, D-3", "A-2, B-3, C-1, D-4"], "answer": 0, "explanation": "Loo is the hot summer wind of the north-western plains; Kalbaisakhi is the Bengal Nor'wester; mango showers ripen mangoes on the south-west coast; blossom showers bring out coffee flowers.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-28", "question": "How many of the following statements about jet streams are correct? I. The tropical easterly jet lies over peninsular India in summer. II. In winter the subtropical westerly jet lies south of the Himalaya. III. Jet streams blow in the lower troposphere, close to the surface. IV. Western disturbances are steered towards India by the westerly jet.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: jet streams are narrow belts of fast wind in the upper troposphere, around 9–14 km up.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-29", "question": "Which of the following is NOT one of the conditions that help the onset of the south-west monsoon?", "options": ["Differential heating of the Indian landmass and the surrounding seas", "Northward shift of the ITCZ over the Ganga plain", "The subtropical westerly jet staying south of the Himalaya through June", "A high-pressure area east of Madagascar (the Mascarene High)"], "answer": 2, "explanation": "The westerly jet must move north of the Himalaya for the monsoon to advance; if it stays south, the onset is held back. The other three are standard factors in the onset.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-30", "question": "Arrange the following in the order in which the south-west monsoon normally reaches them: 1. Delhi  2. Thiruvananthapuram  3. Western Rajasthan (Jaisalmer)  4. Mumbai", "options": ["2-3-4-1", "1-4-3-2", "3-4-2-1", "2-4-1-3"], "answer": 3, "explanation": "Normal onset: Thiruvananthapuram about 1 June, Mumbai about 11 June, Delhi in late June, and west Rajasthan last, when the monsoon covers the whole country around 8 July.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-31", "question": "How many of the following statements about rainfall in India are correct? I. Roughly three-fourths of India's annual rainfall comes during June–September. II. Parts of the Khasi and Jaintia hills receive more than 1000 cm of rain a year. III. Across the northern plains, rainfall decreases from east to west. IV. Tamil Nadu receives most of its annual rainfall during June–September.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: Tamil Nadu gets most of its rain from October to December from the north-east monsoon and cyclones.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-32", "question": "Assertion (A): The Coromandel coast receives heavy rainfall in October–November. Reason (R): In October–November the south-west monsoon winds blow directly onto the Tamil Nadu coast.", "options": ["A is true but R is false", "Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], "answer": 0, "explanation": "A is true, but the rain comes from north-east winds and cyclonic depressions that pick up moisture over the Bay of Bengal, not from the south-west monsoon, which has withdrawn by then. So R is false.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-33", "question": "Which of these places is NOT on the windward side of the Western Ghats?", "options": ["Mangaluru", "Bengaluru", "Mumbai", "Kozhikode"], "answer": 1, "explanation": "Mangaluru, Mumbai and Kozhikode lie on the coast facing the Arabian Sea branch and get heavy rain; Bengaluru sits on the plateau in the rain shadow, with much lower rainfall.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-34", "question": "How many of the following statements about tropical cyclones are correct? I. In the northern hemisphere, winds around a cyclone rotate anticlockwise. II. The strongest winds of a cyclone are found inside its eye. III. Cyclones usually intensify after landfall because of friction with land. IV. Storm surge is a major cause of deaths when a cyclone strikes a coast.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and IV are correct. The eye is calm with the lowest pressure; the strongest winds are in the eyewall (II wrong). Cyclones weaken after landfall as they lose their moisture supply and face friction (III wrong).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-35", "question": "Which of the following pairs is NOT correctly matched?", "options": ["Tropical easterly jet — upper-level wind over the peninsula in summer", "Western disturbance — winter rain in Punjab", "Loo — humid evening thunderstorms in Assam", "Mascarene High — high pressure near Madagascar"], "answer": 2, "explanation": "The Loo is a hot, dry afternoon wind of the north-western plains in May–June; humid evening storms in Assam are the Nor'westers (Bardoli Chheerha).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-36", "question": "Match the Köppen climate type with the region of India where it is found. A. Amw  B. As  C. BWhw  D. Dfc; 1. Coromandel coast of Tamil Nadu  2. Arunachal Pradesh  3. West coast south of Goa  4. Extreme western Rajasthan", "options": ["A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-4, B-1, C-3, D-2", "A-3, B-2, C-4, D-1"], "answer": 0, "explanation": "Amw (monsoon with a short dry season) covers the west coast south of Goa; As (dry summer) the Coromandel coast; BWhw (hot desert) extreme west Rajasthan; Dfc (cold humid winter, short summer) Arunachal Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-37", "question": "Which of these pairs of storm name and region is NOT correct?", "options": ["Tornado — tropical cyclone of the Indian Ocean", "Willy-willy — north-western Australia", "Hurricane — Caribbean and North Atlantic", "Typhoon — north-west Pacific and South China Sea"], "answer": 0, "explanation": "Indian Ocean storms are simply called cyclones. A tornado is a small, very intense funnel of wind over land, best known in the central USA, not a tropical cyclone.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-38", "question": "Which of these stations has the lowest annual range of temperature?", "options": ["Delhi", "Leh", "Bikaner", "Thiruvananthapuram"], "answer": 3, "explanation": "Thiruvananthapuram is near the equator and the sea, so maritime influence keeps its annual range to a few degrees; Delhi, Bikaner and Leh are continental with large ranges.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-39", "question": "How many of the following statements about the retreating monsoon are correct? I. The monsoon withdraws from north-west India first. II. During the retreat the monsoon trough weakens and shifts south. III. Cyclones that form over the Andaman Sea in October–November often cross the eastern coast. IV. The retreating monsoon gives Punjab most of its annual rainfall.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: Punjab gets most of its rain in July–September from the advancing south-west monsoon, with some winter rain from western disturbances.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-40", "question": "How many of the following pairs of place and its main rainy period are correctly matched? I. Chennai — October to December  II. Srinagar — July to August, from the south-west monsoon  III. Mumbai — June to September", "options": ["Only one", "Only two", "All three", "None"], "answer": 1, "explanation": "Chennai gets its rain in Oct–Dec and Mumbai in Jun–Sep. Srinagar, shielded by the Pir Panjal, gets most of its precipitation in late winter and spring (peaking around March) from western disturbances, so II is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-41", "question": "A line on a map joining places that receive the same amount of rainfall is called an:", "options": ["Isotherm", "Isobar", "Isohyet", "Isohel"], "answer": 2, "explanation": "An isohyet joins points of equal rainfall. Isotherms join equal temperature, isobars equal pressure and isohels equal sunshine.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-42", "question": "Mumbai receives its heavy June–September rain mainly from the:", "options": ["Bay of Bengal branch of the south-west monsoon", "Arabian Sea branch of the south-west monsoon", "North-east monsoon", "Western disturbances"], "answer": 1, "explanation": "The Arabian Sea branch strikes the west coast and the Western Ghats, drenching Mumbai and the Konkan. The Bay of Bengal branch serves the north-east and the Ganga plain.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-43", "question": "According to the IMD, the south-west monsoon season covers the months of:", "options": ["March–May", "October–December", "January–February", "June–September"], "answer": 3, "explanation": "The IMD's four seasons are winter (Jan–Feb), pre-monsoon (Mar–May), south-west monsoon (Jun–Sep) and post-monsoon (Oct–Dec).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-44", "question": "In winter, the prevailing monsoon winds over most of India blow from the:", "options": ["North-east", "South-west", "South-east", "West"], "answer": 0, "explanation": "In winter a high-pressure area over north-west India and Central Asia sends cold, dry winds outward from land to sea; over India they blow from the north-east.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-45", "question": "In May, the highest day temperatures in India are usually recorded in:", "options": ["The Nilgiri hills", "Coastal Kerala", "North-western India, especially Rajasthan", "Meghalaya"], "answer": 2, "explanation": "With the sun high and dry, clear skies, the Thar region of Rajasthan records 45 °C or more in May–June; coasts and hills stay much cooler.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-46", "question": "Mawsynram and Cherrapunji receive extremely heavy rainfall mainly because:", "options": ["They lie on the leeward side of the Khasi hills", "Western disturbances bring them heavy winter snow", "The north-east monsoon strikes them head-on in December", "The funnel-shaped Khasi hills trap the moist Bay of Bengal branch and force it to rise steeply"], "answer": 3, "explanation": "The southern face of the Khasi hills forms a funnel that catches the moisture-laden Bay of Bengal branch; forced ascent gives very heavy orographic rain. Their rain comes from the south-west monsoon, not winter systems.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-47", "question": "Leh in Ladakh is a cold desert mainly because it:", "options": ["Lies in the rain shadow of the Great Himalaya and is at a high altitude", "Is far from the Tropic of Cancer", "Receives the north-east monsoon in winter", "Lies on the windward side of the Pir Panjal"], "answer": 0, "explanation": "The Great Himalaya blocks the monsoon, so Leh gets only about 10 cm of precipitation a year, and its height of about 3,500 m keeps it cold.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-48", "question": "The distribution of south-west monsoon rainfall over India is governed to a large extent by:", "options": ["The Coriolis force alone", "Relief: windward slopes get heavy rain and leeward areas little", "Latitude: rain increases steadily northward", "The distance from the Tropic of Capricorn"], "answer": 1, "explanation": "NCERT notes that monsoon rainfall is largely relief-governed: the Western Ghats and north-eastern hills get heavy rain on their windward sides while the Deccan interior and Ladakh lie in rain shadow.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-49", "question": "As per the IMD's revised normal dates (2020), by about which date does the south-west monsoon normally cover the whole of India?", "options": ["1 June", "15 September", "8 July", "15 October"], "answer": 2, "explanation": "The revised normal date for the monsoon to cover the entire country is 8 July. 1 June is the onset over Kerala, and 15 October is the normal date of complete withdrawal.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-50", "question": "Which of these regions does NOT normally receive more than 200 cm of rainfall a year?", "options": ["The Konkan and Malabar coast", "The Andaman and Nicobar Islands", "The southern slopes of the Meghalaya plateau", "Interior Marathwada in Maharashtra"], "answer": 3, "explanation": "Marathwada lies in the rain shadow of the Western Ghats and gets roughly 50–100 cm. The west coast, Andamans and Meghalaya slopes all exceed 200 cm.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-51", "question": "The diurnal (day–night) range of temperature in India is greatest in:", "options": ["The Thar desert", "Coastal Kerala", "The Sundarbans delta", "The Lakshadweep islands"], "answer": 0, "explanation": "Dry air and clear skies let desert sand heat strongly by day and lose heat fast at night, so the Thar can swing by 20 °C or more in a day. Coasts and islands are moderated by the sea.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-52", "question": "The centre of a large city is often several degrees warmer than the surrounding countryside, especially at night. This is called:", "options": ["Temperature inversion", "The urban heat island effect", "Advection fog", "The Föhn effect"], "answer": 1, "explanation": "Concrete and asphalt store heat by day and release it at night, and traffic and buildings add waste heat, creating an urban heat island. An inversion is temperature rising with height.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-53", "question": "Clear, cold nights with ground frost in north India in December–January are mainly due to:", "options": ["Heavy cloud cover from the south-west monsoon", "Warm, moist winds from the Bay of Bengal", "Dry continental air and clear skies under high pressure, which let the ground lose heat rapidly", "The tropical easterly jet"], "answer": 2, "explanation": "In winter, high pressure brings calm, dry air and cloudless skies, so the ground radiates heat away at night and temperatures can fall below freezing in Punjab and Haryana.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-54", "question": "On average, the temperature in the troposphere falls with height at about:", "options": ["1 °C per 100 km", "6.5 °C per 1,000 m", "10 °C per 100 m", "0.5 °C per 1,000 m"], "answer": 1, "explanation": "The normal lapse rate is about 6.5 °C per 1,000 m, which is why hill stations like Shimla and Ooty are much cooler than the plains below them.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-climate-monsoon-55", "question": "The IMD uses all of the following criteria when it declares the onset of the monsoon over Kerala EXCEPT:", "options": ["Rainfall at a set of 14 stations in Kerala and nearby for two consecutive days", "The depth and strength of the westerly winds", "Outgoing longwave radiation, a measure of cloudiness", "A rise in the sea level at Kochi harbour"], "answer": 3, "explanation": "Since 2006 the IMD checks rainfall at 14 listed stations (after 10 May), the westerly wind field and outgoing longwave radiation. Sea level at a harbour is not a criterion.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-56", "question": "After being deflected by the Himalaya, the Bay of Bengal branch of the monsoon moves over the Ganga plain:", "options": ["From north-west to south-east", "From south-west to north-east", "From east and south-east towards the west and north-west", "From north to south"], "answer": 2, "explanation": "Turned by the Arakan hills and the Himalaya, the Bay branch flows westward up the Ganga plain, which is why its rain weakens from Kolkata towards Punjab. It does not blow from the south-west there.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-57", "question": "The Bay of Bengal sees many more tropical cyclones than the Arabian Sea mainly because the Bay has:", "options": ["Colder surface waters due to strong upwelling", "Warmer surface waters and receives remnants of low-pressure systems moving in from the western Pacific", "Stronger vertical wind shear throughout the year", "No Coriolis force over it"], "answer": 1, "explanation": "The Bay is warmer and is regularly seeded by the remnants of western Pacific systems crossing South-East Asia. The Arabian Sea is cooler, partly because of upwelling off Somalia and Oman.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-58", "question": "For a station in the plains, the IMD does not consider a heat wave unless the station's maximum temperature reaches at least:", "options": ["35 °C", "45 °C", "47 °C", "40 °C"], "answer": 3, "explanation": "The IMD's thresholds are 40 °C for plains, 37 °C for coastal stations and 30 °C for hill stations, together with a departure of at least 4.5 °C from normal (or an actual 45 °C or more).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-59", "question": "Before setting in over Kerala, the south-west monsoon normally first advances over:", "options": ["The Andaman Sea and the Andaman and Nicobar Islands", "Gujarat", "The Lakshadweep islands in July", "Sri Lanka's northern tip in August"], "answer": 0, "explanation": "The monsoon normally reaches the south Andaman Sea around 20–22 May, about ten days before its onset over Kerala around 1 June.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-60", "question": "Thiruvananthapuram gets rain in June–July and then a second rainfall peak in October–November. The second peak is due mainly to:", "options": ["Western disturbances", "The retreating and north-east monsoon, with depressions crossing the southern peninsula", "The Loo", "Convection over the Thar desert"], "answer": 1, "explanation": "The southern tip of Kerala gets the south-west monsoon first and then rain from the retreating/north-east monsoon and Bay of Bengal depressions in October–November, giving two maxima.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-61", "question": "Cold waves in north India often follow the passage of a western disturbance because:", "options": ["Warm air from the Arabian Sea follows the disturbance", "The disturbance raises surface pressure over the Bay of Bengal", "Cold, dry north-westerly winds from the snow-covered mountains flow in behind it", "The monsoon trough moves over Delhi"], "answer": 2, "explanation": "As a western disturbance moves east, cold, dry north-westerly winds flow in behind it, often over freshly snow-covered Himalaya, so temperatures plunge.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-62", "question": "In hilly regions, orchards and tea gardens are usually planted on the slopes rather than on the valley floor mainly because:", "options": ["Valley floors always receive less rain", "Cold air drains downslope at night and collects in valleys, causing frost (temperature inversion)", "Slopes receive no sunlight", "Valley soils are always saline"], "answer": 1, "explanation": "On calm, clear nights dense cold air sinks into valleys, so the valley floor can be colder than the slopes above. That inversion brings frost that damages crops.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-63", "question": "All of the following give Tamil Nadu rain in October–December EXCEPT:", "options": ["The north-east monsoon winds after crossing the Bay of Bengal", "Depressions and cyclones from the Bay of Bengal", "Western disturbances", "The retreating monsoon"], "answer": 2, "explanation": "Western disturbances affect north and north-west India, mainly Jammu and Kashmir, Himachal, Punjab and Haryana. Tamil Nadu's winter rain comes from Bay of Bengal systems and the north-east monsoon.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-64", "question": "Very few severe cyclones form over the north Indian Ocean during July–August mainly because:", "options": ["Sea-surface temperatures fall below 15 °C", "Strong vertical wind shear between the low-level westerlies and the upper-level easterly jet tears developing storms apart", "The Coriolis force disappears in summer", "The ITCZ moves south of the equator"], "answer": 1, "explanation": "During the peak monsoon, low-level westerlies sit beneath the upper easterly jet. This strong shear stops storms from building vertically, so monsoon depressions form instead of severe cyclones.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-65", "question": "As per the IMD's revised normal dates, the monsoon normally reaches Mumbai around:", "options": ["11 June", "1 June", "1 July", "15 July"], "answer": 0, "explanation": "The revised normal onset date for Mumbai is 11 June (earlier 10 June). 1 June is Kerala, around the end of June is Delhi, and 8 July is the date for covering the whole country.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-66", "question": "According to the IMD's normal dates, the south-west monsoon withdraws completely from the country by about:", "options": ["1 September", "15 October", "30 November", "31 December"], "answer": 1, "explanation": "Withdrawal begins from west Rajasthan around 17 September and is normally complete by about 15 October. The post-monsoon (north-east monsoon) season then follows.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-67", "question": "Shillong receives much less rain than Cherrapunji although the two are close to each other, because Shillong:", "options": ["Is at a much lower altitude", "Gets no south-west monsoon at all", "Lies on the leeward side, in the rain shadow of the southern Khasi ridge", "Is affected mainly by western disturbances"], "answer": 2, "explanation": "Moist winds dump most of their rain on the southern edge of the Khasi hills around Cherrapunji; Shillong, beyond the crest, gets only a fraction of it.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-68", "question": "How many of the following statements about the IMD's classification of all-India south-west monsoon rainfall are correct? I. Rainfall between 96% and 104% of the Long Period Average (LPA) is 'normal'. II. Rainfall below 90% of the LPA is 'deficient'. III. Seasonal rainfall of 107% of the LPA is classed as 'excess'. IV. The LPA is an average of June–September rainfall over a 50-year period.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. 104–110% of the LPA is 'above normal'; only more than 110% is 'excess', so III is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-69", "question": "Match the isoline with what it joins. A. Isohyet  B. Isohel  C. Isoneph  D. Isobar; 1. Equal duration of sunshine  2. Equal cloudiness  3. Equal atmospheric pressure  4. Equal rainfall", "options": ["A-4, B-2, C-1, D-3", "A-4, B-1, C-2, D-3", "A-3, B-1, C-2, D-4", "A-4, B-1, C-3, D-2"], "answer": 1, "explanation": "Isohyet = rainfall, isohel = sunshine (helios, sun), isoneph = cloudiness (nephos, cloud), isobar = pressure. The usual trap is mixing up isohel and isoneph.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-70", "question": "How many of the following statements are correct? I. The Madden–Julian Oscillation (MJO) is an eastward-moving belt of enhanced cloud and rain along the tropics. II. An active MJO phase over the Indian Ocean tends to strengthen monsoon rainfall over India. III. The Tibetan plateau acts as a cold source in summer and weakens the monsoon circulation. IV. The IMD counts a day as a 'rainy day' when it records 2.5 mm of rain or more.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. In summer the Tibetan plateau is a strong elevated heat source that builds an upper-level high and helps the easterly jet and the monsoon, so III is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-71", "question": "Match the term with its description. A. Elephanta  B. Cloudburst  C. Monsoon break  D. Radiation fog; 1. A spell of days in July–August when rain largely stops over the plains and central India  2. Fog formed on clear, calm winter nights as the ground loses heat  3. Strong winds on the Malabar coast that mark the end of the south-west monsoon  4. About 100 mm or more of rain in an hour over a small area", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-1, B-4, C-3, D-2"], "answer": 0, "explanation": "Elephanta winds blow on the Malabar coast in September–October; the IMD calls 100 mm/hour or more over about 20–30 km² a cloudburst; breaks are dry spells within the monsoon; radiation fog blankets the Indo-Gangetic plain on calm winter nights.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-72", "question": "Assertion (A): Western Rajasthan receives scanty rainfall. Reason (R): The year-to-year variability of rainfall in western Rajasthan is very high.", "options": ["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A"], "answer": 3, "explanation": "Both are true, but high variability is a result of low, unreliable rain, not its cause. The rain is scanty because the Aravallis run parallel to the Arabian Sea branch and the Bay branch arrives exhausted.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-73", "question": "Arrange these places in decreasing order of average annual rainfall: 1. Delhi  2. Mumbai  3. Leh  4. Kolkata", "options": ["2-1-4-3", "4-2-1-3", "2-4-1-3", "2-4-3-1"], "answer": 2, "explanation": "Mumbai gets roughly 220–250 cm, Kolkata about 160–180 cm, Delhi about 75 cm and Leh only about 10 cm. So 2-4-1-3.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-74", "question": "Arrange these weather events in the order they normally occur in a calendar year at Delhi: 1. Onset of the south-west monsoon  2. Peak of the Loo  3. Western disturbance rain that helps the rabi crop  4. October heat", "options": ["3-2-1-4", "2-3-1-4", "3-1-2-4", "3-2-4-1"], "answer": 0, "explanation": "Western disturbances bring winter rain in January–February, the Loo peaks in May–early June, the monsoon reaches Delhi around the end of June, and October heat follows its withdrawal.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-75", "question": "Which of the following statements about western disturbances is NOT correct?", "options": ["They originate over the Mediterranean and West Asian region", "They move eastward towards India", "They are tropical cyclones that form over the Bay of Bengal", "They bring snowfall to the western Himalaya"], "answer": 2, "explanation": "Western disturbances are extra-tropical low-pressure systems that travel east from the Mediterranean region, bringing winter rain and snow to north-west India. They are not tropical cyclones.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-76", "question": "How many of the following statements help explain why the Thar region receives little rain? I. The Aravallis run parallel to the Arabian Sea branch and do not force it to rise. II. The Bay of Bengal branch has shed most of its moisture by the time it reaches western Rajasthan. III. Hot, dry, subsiding air above the region discourages cloud formation. IV. The region lies in the rain shadow of the Western Ghats.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are valid. The Western Ghats shadow the Deccan interior, not Rajasthan, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-77", "question": "Which of the following pairs of place and climatic feature is NOT correct?", "options": ["Leh — cold arid climate", "Mumbai — most rain falls in June–September", "Thiruvananthapuram — rain from both the south-west and the retreating monsoon", "Amritsar — very small annual range of temperature"], "answer": 3, "explanation": "Amritsar, far from the sea, has a continental climate with a large annual range: cold winters and summers above 40 °C. The other pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-78", "question": "How many of the following statements about naming tropical cyclones in the north Indian Ocean are correct? I. Names are assigned by RSMC New Delhi from a list prepared by member countries of the WMO/ESCAP Panel on Tropical Cyclones. II. The panel now has 13 member countries. III. A name once used is not used again. IV. Names alternate between male and female, as in the Atlantic.", "options": ["Only three", "Only two", "Only one", "All four"], "answer": 0, "explanation": "I, II and III are correct (the 2020 list of 169 names came from 13 countries). The north Indian Ocean list does not alternate male and female names, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-79", "question": "Match the cyclone with the state where it made landfall. A. Fani (2019)  B. Amphan (2020)  C. Hudhud (2014)  D. Biparjoy (2023); 1. Gujarat  2. Andhra Pradesh  3. West Bengal  4. Odisha", "options": ["A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Fani hit Puri (Odisha), Amphan crossed near the Sundarbans (West Bengal), Hudhud struck Visakhapatnam (Andhra Pradesh) and Biparjoy, an Arabian Sea storm, hit Kutch (Gujarat).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-80", "question": "Arrange these stations in increasing order of annual range of temperature: 1. Delhi  2. Mumbai  3. Kolkata  4. Thiruvananthapuram", "options": ["4-3-2-1", "4-2-3-1", "2-4-3-1", "4-2-1-3"], "answer": 1, "explanation": "Thiruvananthapuram's range is only about 3 °C, Mumbai about 6 °C, Kolkata about 11 °C and Delhi nearly 19 °C. The range grows with latitude and distance from the sea.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-81", "question": "Storm surges are exceptionally high along the coasts of West Bengal and Bangladesh mainly because:", "options": ["The coast there is rocky and steep", "Cyclones there rotate clockwise", "The head of the Bay of Bengal is funnel-shaped with a shallow, gently sloping continental shelf that piles up water", "The Arabian Sea pushes water eastward"], "answer": 2, "explanation": "Wind-driven water cannot spread sideways in the narrowing, shallow head of the Bay, so it piles up into very high surges. Northern-hemisphere cyclones rotate anticlockwise, not clockwise.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-82", "question": "How many of the following statements about the factors controlling India's climate are correct? I. The Tropic of Cancer passes through the middle of India, dividing it into roughly equal halves. II. The Himalaya shields India from cold winds from Central Asia. III. Places far from the sea have a larger range of temperature. IV. Temperature rises with altitude, so hill stations are warmer in summer.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 1, "explanation": "I, II and III are correct. Temperature falls with height (about 6.5 °C per km), which is why hill stations are cooler, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-83", "question": "Which of the following is NOT a condition for a tropical cyclone to form?", "options": ["Sea-surface temperature above about 27 °C", "Enough Coriolis force to start rotation", "Low vertical wind shear", "A location right on the equator"], "answer": 3, "explanation": "The Coriolis force is almost zero on the equator, so cyclones rarely form within about 5° of it. Warm water and low shear are both needed.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-84", "question": "Which pair of monsoon branch and the area it rains on is NOT correct?", "options": ["Arabian Sea branch — Konkan coast", "Bay of Bengal branch — Meghalaya", "Bay of Bengal branch — the Ganga plain", "Arabian Sea branch — Coromandel coast in July"], "answer": 3, "explanation": "The Coromandel coast lies in the rain shadow in July and gets little rain from the Arabian Sea branch; its main rain comes in October–December. The other pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-85", "question": "Assertion (A): Monsoon depressions bring much of the rainfall of the Ganga plain. Reason (R): Monsoon depressions form over the head of the Bay of Bengal and move north-westward along the monsoon trough.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Depressions born over the north Bay travel west-north-west along the trough over Odisha, Madhya Pradesh and the Ganga plain, dropping heavy rain on their way. So R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-86", "question": "A weather station uses which instrument to measure the relative humidity of the air?", "options": ["Barometer", "Hygrometer", "Anemometer", "Rain gauge"], "answer": 1, "explanation": "A hygrometer (for example the wet-and-dry-bulb psychrometer) measures humidity. A barometer measures pressure and an anemometer wind speed.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "geo-climate-monsoon-87", "question": "Almost all clouds, rain, storms and other weather events occur in which layer of the atmosphere?", "options": ["Stratosphere", "Mesosphere", "Troposphere", "Thermosphere"], "answer": 2, "explanation": "The troposphere, the lowest layer, holds nearly all the water vapour and dust, so weather happens there. The stratosphere above is stable and nearly cloud-free, which suits jet aircraft.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "geo-climate-monsoon-88", "question": "The troposphere is thickest over the:", "options": ["Poles", "Tropic of Cancer only in winter", "Mid-latitudes", "Equator"], "answer": 3, "explanation": "Strong heating and convection push the tropopause to about 16–18 km over the equator, against roughly 8 km over the poles.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "geo-climate-monsoon-89", "question": "Dew forms on grass on a clear night when:", "options": ["The grass cools below the dew point of the air in contact with it", "Warm air rises from the ground", "The relative humidity of the air falls sharply", "Wind speed increases after midnight"], "answer": 0, "explanation": "Clear skies let the ground lose heat; once a surface is colder than the dew point, water vapour condenses on it. Wind and cloud cover hinder dew by keeping the surface warmer.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-90", "question": "Which of these surfaces reflects the largest share of the sunlight falling on it (has the highest albedo)?", "options": ["Dark asphalt road", "Dense evergreen forest", "Fresh snow", "Open ocean water"], "answer": 2, "explanation": "Fresh snow reflects roughly 80–90% of incoming sunlight. Forests, open water and asphalt absorb most of it, which is why melting snow cover speeds up warming.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "geo-climate-monsoon-91", "question": "On a sunny afternoon at a coastal town, a breeze blows from the sea towards the land because:", "options": ["The sea heats faster than the land", "The land heats faster, creating lower pressure over it", "The Coriolis force is strongest in the afternoon", "Cold ocean currents push air inland"], "answer": 1, "explanation": "Land has a lower specific heat than water, so it warms faster by day; air over it rises and cooler air from the sea moves in. At night the pattern reverses into a land breeze.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-climate-monsoon-92", "question": "If a parcel of air is warmed without any moisture being added to it, what happens to its humidity?", "options": ["Both absolute and relative humidity rise", "Absolute humidity falls and relative humidity rises", "Relative humidity falls while absolute humidity stays the same", "Both stay the same"], "answer": 2, "explanation": "The actual amount of vapour (absolute humidity) is unchanged, but warmer air can hold more vapour, so relative humidity drops. That is why relative humidity is usually lowest in the afternoon.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-climate-monsoon-93", "question": "Which of these districts of Maharashtra lies in the rain shadow of the Western Ghats and is drought-prone?", "options": ["Ratnagiri", "Sindhudurg", "Raigad", "Solapur"], "answer": 3, "explanation": "Solapur, on the Deccan plateau east of the Ghats, gets only about 50–75 cm of rain. Ratnagiri, Sindhudurg and Raigad are Konkan districts on the windward side and get well over 250 cm.", "difficulty": "hard", "source": "State PSC · UPSC Prelims"},
  {"id": "geo-climate-monsoon-94", "question": "Temperature rises with height in the stratosphere mainly because:", "options": ["Ozone there absorbs ultraviolet radiation from the sun", "Heat from the earth's surface is trapped by clouds", "The air is denser than in the troposphere", "Jet streams generate friction"], "answer": 0, "explanation": "The ozone layer absorbs solar ultraviolet radiation and warms the upper stratosphere. In the troposphere, by contrast, air is heated from the ground, so temperature falls with height.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-95", "question": "The “horse latitudes”, known for calm winds and dry sinking air, correspond to the:", "options": ["Equatorial low-pressure belt", "Subtropical high-pressure belts at about 30°–35° N and S", "Subpolar low-pressure belts at about 60°", "Polar highs"], "answer": 1, "explanation": "Air that rose at the equator sinks around 30°–35° latitude, forming the subtropical highs with light winds; most hot deserts lie here. The calm equatorial belt is the doldrums.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-96", "question": "A wet-bulb temperature of about 35 °C is widely cited as the theoretical upper limit for human survival over several hours because:", "options": ["Sweat can no longer evaporate fast enough to cool the body", "Blood begins to boil at that temperature", "Oxygen in the air falls sharply at high humidity", "Ultraviolet radiation peaks at that temperature"], "answer": 0, "explanation": "Wet-bulb temperature combines heat and humidity. When it nears skin temperature, evaporation of sweat stops cooling the body, so even a resting, shaded person overheats. Dry-bulb heat alone is far less dangerous.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-97", "question": "On calm nights in hilly areas, cool dense air flowing down the slopes into the valley is called a:", "options": ["Valley breeze", "Sea breeze", "Mountain (katabatic) wind", "Land breeze"], "answer": 2, "explanation": "At night the slopes cool quickly and the chilled air drains downhill as a katabatic or mountain wind. By day warm air moves up the slopes as a valley (anabatic) breeze.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-climate-monsoon-98", "question": "Large hailstones grow mainly because:", "options": ["Raindrops freeze while falling through warm air near the ground", "Strong updrafts in cumulonimbus clouds carry ice pellets repeatedly through layers of supercooled water", "Fog particles stick together at night", "Snowflakes melt and refreeze on cirrus clouds"], "answer": 1, "explanation": "In a towering cumulonimbus, updrafts toss ice pellets up and down; each trip adds a coat of frozen supercooled water, building layered hailstones until they are too heavy to hold up.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-climate-monsoon-99", "question": "The Coriolis force, which deflects moving air, is:", "options": ["Greatest at the equator and zero at the poles", "Equal at all latitudes", "Present only in the southern hemisphere", "Zero at the equator and greatest at the poles"], "answer": 3, "explanation": "The Coriolis effect is proportional to the sine of latitude: zero at the equator and maximum at the poles. That is why cyclones rarely form within about 5° of the equator.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-climate-monsoon-100", "question": "How many of the following statements are correct? I. Rising air cools because it expands under lower pressure. II. Saturated rising air cools more slowly than dry air because condensation releases latent heat. III. Air descending the leeward slope of a range warms by compression. IV. In an adiabatic process the air loses heat to its surroundings.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct; the dry rate is about 9.8 °C per km against roughly 5–6 °C for saturated air. IV is wrong: adiabatic means no heat is exchanged with the surroundings; the change comes from expansion or compression.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-101", "question": "Match the cloud type with its description. A. Cirrus  B. Cumulonimbus  C. Stratus  D. Nimbostratus; 1. Low, grey, uniform sheet that may give drizzle  2. Thick, dark layer giving steady, prolonged rain or snow  3. High, thin, feathery cloud of ice crystals  4. Towering cloud bringing thunder, lightning and hail", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Cirrus are high ice-crystal wisps; cumulonimbus are the thunderstorm clouds; stratus form a low grey sheet; nimbostratus bring long spells of steady rain. Mixing up stratus and nimbostratus is the usual trap.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-102", "question": "Assertion (A): Coastal towns have a smaller daily range of temperature than towns deep in the interior. Reason (R): Water has a higher specific heat than land, so the sea warms and cools slowly.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "The sea's slow heating and cooling, together with sea and land breezes, moderates coastal temperatures; this is the maritime influence that keeps Mumbai's range far below Delhi's.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-climate-monsoon-103", "question": "Arrange the following in increasing order of their typical height above the ground: 1. Peak concentration of the ozone layer  2. Tropopause over the equator  3. Mesopause  4. Kármán line", "options": ["1-2-3-4", "2-1-3-4", "2-1-4-3", "1-2-4-3"], "answer": 1, "explanation": "The equatorial tropopause is about 16–18 km up, ozone peaks at roughly 20–25 km in the stratosphere, the mesopause lies near 85 km and the Kármán line, a conventional edge of space, at 100 km.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-104", "question": "How many of the following generally favour a strong south-west monsoon over India? I. Strong summer heating of the Tibetan plateau. II. A positive Indian Ocean Dipole. III. La Niña conditions in the Pacific. IV. Unusually heavy Eurasian snow cover in the preceding winter and spring.", "options": ["All four", "Only one", "Only two", "Only three"], "answer": 3, "explanation": "I, II and III favour a good monsoon. Heavy Eurasian snow cover uses up spring heat in melting and delays land warming, so it is linked to a weaker monsoon (an idea going back to Blanford); IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-105", "question": "In the Köppen scheme, match the small letter with what it indicates. A. f  B. m  C. w  D. s; 1. Dry season in winter  2. Dry season in summer  3. No dry season, rain in all months  4. Monsoon type, with a short dry season", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-1, B-4, C-3, D-2"], "answer": 0, "explanation": "f = rain all year, m = monsoon with a short dry spell, w = dry winter, s = dry summer. So Aw is tropical savanna with dry winters and As (Coromandel) has its dry season in summer.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-climate-monsoon-106", "question": "How many of the following statements about the Inter-Tropical Convergence Zone (ITCZ) are correct? I. It is where the trade winds of the two hemispheres meet. II. It shifts north and south with the apparent movement of the sun. III. Over the Indian region its northward shift in summer is unusually large. IV. It is a belt of high pressure and sinking air.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct; over India the ITCZ reaches about 20°–25°N in July because of the large landmass. IV is wrong: the ITCZ is a low-pressure zone of rising air, cloud and rain.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"geo-climate-monsoon-107","question":"Moist air at 26 °C at sea level is forced over a 3,000 m mountain range. It cools at the dry adiabatic rate of 10 °C/km until it becomes saturated at 1,000 m, then at the saturated rate of 6 °C/km up to the crest, where it has shed most of its moisture as rain. It then descends the leeward slope to sea level, unsaturated all the way. Its temperature at the leeward foot will be about:","options":["26 °C","22 °C","34 °C","23.5 °C"],"answer":2,"explanation":"Windward: 26 − 10 = 16 °C at 1 km, then 16 − 2 × 6 = 4 °C at the crest. Descending 3 km unsaturated warms it at 10 °C/km to 34 °C. The latent heat released as rain on the windward side is why foehn/chinook winds arrive warm and dry; 26 °C wrongly assumes a symmetric journey.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-108","question":"In the Köppen symbol 'Cwg', used for much of the Ganga plain, the letter 'g' indicates that:","options":["the hottest month comes before the summer solstice and the main rainy season","the winter season is dry","the warmest month has a mean temperature above 22 °C","rain falls mainly in winter and the summer is dry"],"answer":0,"explanation":"'w' already marks the dry winter; 'g' (Ganges type) means the temperature peak comes before the June solstice, in May–June, because monsoon clouds and rain cool the later summer. 'a' denotes a warmest month above 22 °C and 's' a dry summer.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-109","question":"Consider the following statements about explanations of the Indian monsoon: I. The classical thermal concept treats the monsoon as a giant land-and-sea breeze caused by the differential heating of the continent and the ocean. II. Flohn's dynamic concept links the monsoon to the seasonal northward shift of the ITCZ, which draws the equatorial westerlies over South Asia. III. The thermal concept by itself cannot easily account for breaks in the monsoon or its year-to-year variability. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":3,"explanation":"All three are correct. A pure land–sea heating contrast would give a steady monsoon every year, so it cannot explain breaks, sudden onset or inter-annual swings, which modern views tie to the ITCZ, jet streams, ENSO and the IOD.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-110","question":"The 'Mascarene High', often cited as a driver of the strength of the south-west monsoon, is:","options":["a semi-permanent high in the upper troposphere over the Tibetan plateau","a subtropical high-pressure cell over the southern Indian Ocean east of Madagascar, from which air flows across the equator towards India","a winter anticyclone over north-west India that gives rise to the north-east monsoon","a ridge of high pressure over the Arabian Sea that causes breaks in the monsoon"],"answer":1,"explanation":"The Mascarene High lies in the southern subtropical Indian Ocean near the Mascarene Islands; a stronger high pushes more south-east trades across the equator, where they turn into the south-west monsoon. The upper-level high over Tibet is a separate feature.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-111","question":"Arrange these IMD categories of low-pressure systems in increasing order of maximum sustained wind speed: 1. Severe cyclonic storm  2. Deep depression  3. Extremely severe cyclonic storm  4. Very severe cyclonic storm","options":["2, 1, 4, 3","2, 4, 1, 3","1, 2, 4, 3","2, 1, 3, 4"],"answer":0,"explanation":"IMD scale: deep depression 28–33 knots, severe cyclonic storm 48–63, very severe 64–89, extremely severe 90–119 and super cyclonic storm 120 knots or more. 'Very severe' is stronger than 'severe', a frequent slip.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-112","question":"Assertion (A): Places on the leeward side of the Western Ghats, such as Pune, receive far less monsoon rain than the Konkan coast. Reason (R): Air descending the leeward slopes is warmed adiabatically, which lowers its relative humidity.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Having dropped its moisture on the windward slopes, the air sinks and warms by compression on the eastern side, so its relative humidity falls and clouds dissolve, creating the rain-shadow of the Deccan.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PSC"},
  {"id":"geo-climate-monsoon-113","question":"Assertion (A): Tropical cyclones almost never form within about 5° of the equator. Reason (R): Sea-surface temperatures close to the equator are usually below the 26.5–27 °C needed for cyclone formation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Equatorial seas are among the warmest, so R is false. Cyclones cannot form there because the Coriolis force is nearly zero close to the equator and cannot set up the rotating circulation.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-114","question":"Assertion (A): Mumbai receives several times more annual rainfall than Pune. Reason (R): Being on the coast, Mumbai has a smaller annual range of temperature than Pune.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but the rainfall contrast is due to Mumbai lying on the windward side of the Western Ghats and Pune in their rain shadow; the sea's moderating effect explains the temperature range, not the rain.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"geo-climate-monsoon-115","question":"Assertion (A): Kerala receives most of its annual rainfall from the north-east monsoon. Reason (R): Over most of India the north-east (winter) monsoon winds blow from the land towards the sea.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Kerala gets the bulk of its rain from the south-west monsoon in June–September, with only a secondary Oct–Nov peak, so A is false. R is true: the winter monsoon is an offshore land wind except where it crosses the Bay to reach the Coromandel coast.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-116","question":"In summer the upper troposphere over the Tibetan plateau develops a strong anticyclone (high), whose southern flank feeds the tropical easterly jet. This upper-level high forms mainly because:","options":["snow cover on the plateau chills the air above it","western disturbances pile up air over the plateau","the elevated plateau heats the air above it, so the air rises and spreads outward at upper levels","the subtropical westerly jet sinks over the plateau and compresses the air"],"answer":2,"explanation":"At 4–5 km height the plateau acts as an elevated heat source: heated air rises, giving low pressure near the surface but outflow and high pressure aloft, and easterlies on its southern side form the TEJ. Snow cover would weaken, not create, this high.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-117","question":"Which of the following is NOT one of the IMD's criteria for declaring the withdrawal of the south-west monsoon from north-west India?","options":["No rainfall over the area for five consecutive days","An anticyclone established in the lower troposphere, around the 850 hPa level","A marked fall in moisture seen in water-vapour satellite imagery and tephigrams","Outgoing longwave radiation over the area falling below 200 W/m²"],"answer":3,"explanation":"Withdrawal is declared on the first three conditions. Low outgoing longwave radiation (below 200 W/m²) signals deep convective cloud and is used for declaring the onset over Kerala, not the withdrawal.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-118","question":"During a prolonged 'break' in the south-west monsoon, when central India stays largely dry, which region usually receives above-normal rainfall?","options":["The Konkan and Goa coast","The sub-Himalayan belt and north-east India","Gujarat and Saurashtra","The Chhattisgarh basin"],"answer":1,"explanation":"In a break the monsoon trough shifts north to the Himalayan foothills, so rain concentrates along the foothills and over the north-east, often flooding the Brahmaputra and north Bihar rivers, while the plains and the west coast get little.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-119","question":"Spells of very heavy rain along the Konkan and Malabar coasts during the monsoon are usually associated with:","options":["an offshore trough or vortex along the west coast together with strong low-level westerly winds","the shift of the monsoon trough to the Himalayan foothills","the passage of a western disturbance over north India","a weakening of the low-level jet over the Arabian Sea"],"answer":0,"explanation":"An offshore trough with embedded vortices, fed by a strong cross-equatorial low-level jet, sharply increases moisture convergence and orographic lifting on the coast. A foothill position of the trough or a weak low-level jet reduces west-coast rain.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-120","question":"In July, the lowest surface pressure over the Indian subcontinent is normally found over:","options":["the head of the Bay of Bengal","the Kerala coast","the central Deccan plateau","north-western India and adjoining Pakistan"],"answer":3,"explanation":"Intense heating of the arid north-west creates a heat low (around 994 hPa) at the western end of the monsoon trough; the trough extends from there to the head of the Bay, where pressure is a little higher.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-121","question":"Arrange these stations in decreasing order of average annual rainfall: 1. Bengaluru  2. Mangaluru  3. Jaisalmer  4. Chennai","options":["2, 1, 4, 3","2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":1,"explanation":"Mangaluru on the windward coast gets about 3,500 mm, Chennai about 1,400 mm (mostly in Oct–Dec), Bengaluru on the plateau under 1,000 mm and Jaisalmer under 200 mm. Green Bengaluru is often wrongly assumed to be wetter than Chennai.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-122","question":"Dense winter fog over the Indo-Gangetic plain in December–January is favoured by all of the following EXCEPT:","options":["moist ground and air left behind by a passing western disturbance","long, clear nights that allow strong radiative cooling of the ground","calm or very light winds under a high-pressure system","strong surface winds that mix the lower layers of the air"],"answer":3,"explanation":"Radiation fog needs moisture, clear long nights and calm air so that a shallow surface layer cools to its dew point under an inversion. Strong winds mix warmer air downward and break up the inversion, preventing fog.","difficulty":"hard","source":"SSC CGL Tier 2 · State PSC"},
  {"id":"geo-climate-monsoon-123","question":"El Niño years tend to bring a weak monsoon to India. The mechanism most widely accepted for this link is that during an El Niño:","options":["warm water off Peru evaporates extra moisture that is carried to India","the rising branch of the Walker circulation shifts east towards the central Pacific, leaving sinking, rain-suppressing air over the Indian region","the trade winds over the Pacific strengthen and drag moisture away from the Indian Ocean","cold water upwells along the west coast of India and cools the Arabian Sea"],"answer":1,"explanation":"With the warm pool and rising air displaced eastward, the compensating descending limb of the Walker circulation moves over the Indian Ocean and South Asia, suppressing convection. Trade winds weaken, not strengthen, in an El Niño.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-124","question":"A severe cyclone in the Bay of Bengal is moving north-west and is about to cross the Andhra Pradesh coast, which runs roughly south-west to north-east. Along the coast, the highest storm surge is usually expected:","options":["to the right of the track, north-east of the landfall point","to the left of the track, south-west of the landfall point","exactly at the landfall point, under the calm eye","equally on both sides, since the winds are symmetric"],"answer":0,"explanation":"Northern-hemisphere cyclones spin anticlockwise; on the right of the track the storm's forward motion adds to the wind speed and the winds blow onshore, piling water against the coast. On the left side the winds blow offshore.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-125","question":"Match the Köppen climate type with the region where NCERT places it. A. Aw  B. BShw  C. Cwg  D. E; 1. Ganga plain, eastern Rajasthan and most of north-east India  2. Most of the peninsular plateau south of the Tropic of Cancer  3. High mountain areas of Jammu and Kashmir, Himachal Pradesh and Uttarakhand  4. Rain-shadow belt east of the Western Ghats and parts of Rajasthan, Haryana and Gujarat","options":["A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"answer":2,"explanation":"Aw (tropical savanna) covers most of the plateau; BShw (semi-arid steppe) the rain-shadow interior and the margins of the Thar; Cwg (monsoon with dry winter) the Ganga plain; E (polar/highland) the high Himalaya.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-126","question":"An unsaturated air parcel at the surface has a temperature of 30 °C and a dew point of 22 °C. As it rises, its temperature falls at 10 °C per km and its dew point at about 2 °C per km. Clouds will begin to form at a height of about:","options":["800 m","1,333 m","4,000 m","1,000 m"],"answer":3,"explanation":"The gap of 8 °C closes at 10 − 2 = 8 °C per km, so condensation begins at about 1 km. 800 m wrongly assumes the dew point stays fixed; 1,333 m uses the saturated lapse rate before saturation.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-127","question":"How many of these correctly distinguish tropical cyclones from temperate (extra-tropical) cyclones? I. Tropical cyclones have no fronts. II. Tropical cyclones draw their energy mainly from the latent heat released by condensation. III. Tropical cyclones usually cover a larger area than temperate cyclones. IV. Tropical cyclones weaken quickly after moving over land.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: temperate cyclones are much larger, often 1,000–2,000 km across, whereas tropical cyclones are more compact but far more intense.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-128","question":"A ship in the Bay of Bengal finds the wind blowing steadily from the south-west. By Buys Ballot's law, the centre of low pressure lies roughly towards the:","options":["north-west","south-east","north-east","south-west"],"answer":0,"explanation":"Stand with your back to the wind, facing north-east: in the northern hemisphere low pressure lies to the left, i.e. the north-west. North-east confuses where the wind is going with where the low lies; south-east applies the southern-hemisphere rule.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-129","question":"Match the rainfall event with the main type of precipitation. A. Afternoon thunderstorm rain over Kerala in April  B. July rain on the windward slopes of the Western Ghats  C. Winter rain over Punjab from a western disturbance  D. Heavy rain over coastal Odisha from a Bay of Bengal depression; 1. Orographic  2. Convectional  3. Extra-tropical cyclonic  4. Tropical cyclonic","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"answer":2,"explanation":"Pre-monsoon afternoon storms come from surface heating (convectional), Western Ghats rain from forced ascent (orographic), western disturbances are mid-latitude (extra-tropical) lows, and Bay depressions are tropical cyclonic systems.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-130","question":"Consider the following statements: I. Along the Ganga plain, average annual rainfall decreases from east to west. II. Across the peninsula, rainfall decreases from the west coast towards the interior east of the Western Ghats. III. Along the west coast, rainfall increases steadily northwards from Kerala to Gujarat. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"The Bay branch loses moisture as it moves up the plain, and the Ghats leave the interior in rain shadow. III is wrong: the Gujarat coast is far drier than the Konkan and Malabar coasts.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-131","question":"Assertion (A): Around the June solstice, the daily solar radiation received at the top of the atmosphere over north India is greater than that over the equator. Reason (R): In June the noon Sun stands higher in the sky over the equator than over north India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"In June the Sun is overhead near 23.5° N, so at about 28° N the noon Sun is roughly 85° high against about 67° at the equator, and days are longer too; hence A is true and R false. This is why the heat low develops over north-west India.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-132","question":"Arrange these places in the order in which the south-west monsoon normally withdraws from them: 1. Patna  2. Jaisalmer  3. Thiruvananthapuram  4. Delhi","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","3, 1, 4, 2"],"answer":0,"explanation":"Withdrawal begins from west Rajasthan in September, reaches Delhi in late September, Bihar in early October and the far south last, by mid-October. 3, 1, 4, 2 is roughly the order of onset, not withdrawal.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims"},
  {"id":"geo-climate-monsoon-133","question":"On a cloudless summer day Chandigarh (about 350 m above sea level) records 38 °C. Using the normal lapse rate of temperature, the expected temperature at a hill station at about 2,350 m in the same air mass is roughly:","options":["18 °C","25 °C","31.5 °C","22.7 °C"],"answer":1,"explanation":"The height difference is 2,000 m, so 38 − 2 × 6.5 = 25 °C. 22.7 °C wrongly uses the full 2,350 m altitude, and 18 °C uses the dry adiabatic rate meant for rising air parcels.","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-134","question":"How many of these statements about the two branches of the south-west monsoon are correct? I. The Arabian Sea branch is stronger than the Bay of Bengal branch. II. Part of the Arabian Sea branch crosses central India and mingles with the Bay of Bengal branch over the northern plains. III. Part of the Bay of Bengal branch is deflected towards India by the Arakan hills along the coast of Myanmar. IV. The Bay of Bengal branch is turned eastward by the Himalaya and so never reaches Punjab.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Himalaya deflect the Bay branch westward up the Ganga plain, and it does reach Punjab and Haryana, though with much less moisture, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-135","question":"Which of the following have generally been associated with a WEAKER south-west monsoon over India? I. An El Niño developing in the Pacific  II. A positive Indian Ocean Dipole  III. Unusually extensive Eurasian and Himalayan snow cover in the preceding winter and spring  IV. Strong pre-monsoon heating of the Tibetan plateau","options":["I and III only","I, III and IV only","I only","I, II and III only"],"answer":0,"explanation":"Blanford noticed in the 1880s that heavy Himalayan snow precedes weak monsoons: energy goes into melting snow instead of heating the land. A positive IOD and strong Tibetan heating favour a stronger monsoon.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-136","question":"Assertion (A): Western disturbances affect north-west India far more often in winter than in summer. Reason (R): In winter the subtropical westerly jet lies south of the Himalaya and steers these systems towards India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Western disturbances travel embedded in the westerly jet. In summer the jet shifts north of the Tibetan plateau, so these lows are steered away from India, which is why winter rain in Punjab and snow in Kashmir come mainly from them.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-137","question":"Under the widely used Oceanic Niño Index (ONI), El Niño conditions are said to exist when:","options":["sea-surface temperature off the coast of Peru alone rises 0.5 °C above normal for a single month","the Southern Oscillation Index stays strongly positive for three months","sea-surface temperature in the western Pacific warm pool exceeds 30 °C","the three-month running mean sea-surface temperature anomaly in the Niño 3.4 region of the equatorial Pacific is +0.5 °C or more"],"answer":3,"explanation":"The ONI uses the central-equatorial Niño 3.4 box, not the Peru coast (Niño 1+2). El Niño goes with a negative, not positive, Southern Oscillation Index.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-138","question":"Consider the following statements about the Arabian Sea: I. Its surface temperature typically falls from a peak in May to a minimum in July–August. II. This cooling is caused mainly by strong monsoon winds that drive upwelling along the Somali and Arabian coasts, mix the upper ocean and increase evaporation. III. Partly because of this, cyclones over the Arabian Sea are concentrated in the pre-monsoon and post-monsoon months. Which of the statements given above is/are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"The monsoon winds themselves cool the Arabian Sea through upwelling, mixing and evaporation, and also create strong vertical wind shear, so cyclones there cluster in May–June and October–November.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-139","question":"A station records 210 mm of rain in 24 hours. Under the IMD's terminology for daily rainfall at a station, this is described as:","options":["heavy rainfall","very heavy rainfall","extremely heavy rainfall","a cloudburst"],"answer":2,"explanation":"IMD: heavy 64.5–115.5 mm, very heavy 115.6–204.4 mm, extremely heavy 204.5 mm or more. A cloudburst means about 100 mm or more in an hour over a small area, so a daily total alone does not make one.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-140","question":"Match the traditional Indian season with its months in the Hindu calendar. A. Vasanta  B. Grishma  C. Sharad  D. Shishira; 1. Magha–Phalguna  2. Chaitra–Vaisakha  3. Jyeshtha–Ashadha  4. Ashvin–Kartika","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"The six ritus run Vasanta (Chaitra–Vaisakha), Grishma (Jyeshtha–Ashadha), Varsha (Shravana–Bhadrapada), Sharad (Ashvin–Kartika), Hemanta (Margashirsha–Pausha) and Shishira (Magha–Phalguna).","difficulty":"moderate","source":"SSC CGL Tier 2"},
  {"id":"geo-climate-monsoon-141","question":"The north–south difference in temperature across India is large in January but small in July. The best explanation is that:","options":["in January the moderating influence of the sea reaches across the whole northern plain","in July the Sun is high over the whole country and days are longer in the north, while in January the north gets oblique rays, short days and cold air behind western disturbances","in July the Himalaya trap warm air over the south while letting cold air into the north","the north-east monsoon brings warm air to the north in July"],"answer":1,"explanation":"In summer the high Sun and long days of the north offset its latitude, so the north becomes as hot as or hotter than the south; in winter low sun angle, short days and cold continental air make the north much colder than the tropical south.","difficulty":"hard","source":"SSC CGL Tier 2 · State PSC"},
  {"id":"geo-climate-monsoon-142","question":"How many of these statements about monsoon depressions are correct? I. Most of them form over the north Bay of Bengal. II. They usually move west-north-west along the monsoon trough. III. Their heaviest rain usually falls in the south-west sector of the system. IV. Like mature cyclones, they have a calm, cloud-free eye.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; monsoon depressions are weaker systems without an eye and bring much of central and north India's monsoon rain, concentrated in their south-west sector, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"geo-climate-monsoon-143","question":"Station P has a mean annual rainfall of 250 mm with a standard deviation of 100 mm; station Q has a mean of 2,500 mm with a standard deviation of 400 mm. Which statement is correct?","options":["Q's rainfall is more variable, because its standard deviation is four times larger","P's rainfall is more variable: its coefficient of variation is 40% against 16% for Q","Both are equally variable, since variability depends only on the mean","P's coefficient of variation is 4% and Q's is 16%"],"answer":1,"explanation":"Coefficient of variation = SD/mean: 100/250 = 40% for P and 400/2,500 = 16% for Q. This is why low-rainfall areas like western Rajasthan have the least dependable rain even though wet areas swing more in absolute millimetres.","difficulty":"hard","source":"SSC CGL Tier 2"},
];

